def solve(s: str) -> bool:
    """Return True if brackets in s are balanced.
    Considers (), [], {}. Ignores other characters.
    """
    stack = []
    pairs = {'(': ')', '[': ']', '{': '}'}
    closing = set(pairs.values())
    for ch in s:
        if ch in pairs:
            stack.append(pairs[ch])
        elif ch in closing:
            if not stack or stack.pop() != ch:
                return False
    return not stack

