def solve(mat):
    """Return determinant of a square integer matrix.
    Empty matrix has determinant 1.
    Uses Bareiss algorithm (fraction-free Gaussian elimination) for exact integer result.
    """
    if not mat:
        return 1
    n = len(mat)
    # Verify square
    for row in mat:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a copy as list of lists
    a = [list(map(int, row)) for row in mat]
    det = 1
    for k in range(n-1):
        # Find pivot
        if a[k][k] == 0:
            # Find a non-zero pivot below
            for i in range(k+1, n):
                if a[i][k] != 0:
                    a[k], a[i] = a[i], a[k]
                    det = -det
                    break
            else:
                return 0
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Bareiss formula
                a[i][j] = (a[i][j]*a[k][k] - a[i][k]*a[k][j]) // (a[k-1][k-1] if k>0 else 1)
        # Zero out below pivot column
        for i in range(k+1, n):
            a[i][k] = 0
    return det * a[n-1][n-1]

