def solve(n):
    """Return the number of prime numbers strictly less than n.
    Handles n <= 2 and negative values by returning 0.
    Uses Sieve of Eratosthenes for efficiency.
    """
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit+1:p] = b'\x00' * ((limit - start) // p + 1)
    return sum(sieve)

