def solve(s):
    """Check if brackets in the string are balanced.
    Considers (), [], {} and ignores all other characters.
    Returns True if every opening bracket has a matching closing bracket
    in correct order, otherwise False.
    """
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

