def solve(coins, amount):
    """Return the minimum number of coins needed to make *amount* using
    unlimited copies of each coin in *coins*. If it is impossible, return -1.
    Handles edge cases such as empty *coins* list and non‑positive *amount*.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # DP array where dp[i] = minimal coins to make amount i, initialized to INF
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
                cand = dp[a - c] + 1
                if cand < best:
                    best = cand
        dp[a] = best
    return dp[amount] if dp[amount] != INF else -1

