def solve(matrix):
    """Return the determinant of a square integer matrix using Bareiss algorithm."""
    n = len(matrix)
    if n == 0:
        return 1  # determinant of 0x0 matrix conventionally 1
    # make a copy as mutable list of lists
    A = [row[:] for row in matrix]
    det = 1
    for k in range(n-1):
        # find pivot
        if A[k][k] == 0:
            # find non-zero pivot below
            for i in range(k+1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det = -det
                    break
            else:
                return 0
        for i in range(k+1, n):
            for j in range(k+1, n):
                A[i][j] = (A[i][j]*A[k][k] - A[i][k]*A[k][j]) // (A[k-1][k-1] if k>0 else 1)
            A[i][k] = 0
    return det * A[n-1][n-1]

