    """Return determinant of a square integer matrix.
    Empty matrix has determinant 1.
    Uses exact Gaussian elimination with Fraction to avoid rounding errors.
    """
    if not mat:
        return 1
    n = len(mat)
    # check square
    for row in mat:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    from fractions import Fraction
    # copy as Fractions
    a = [[Fraction(x) for x in row] for row in mat]
    det = Fraction(1)
    for i in range(n):
        # find pivot
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            det = -det
        pivot_val = a[i][i]
        det *= pivot_val
        # normalize row i
        for j in range(i+1, n):
            a[i][j] /= pivot_val
        a[i][i] = Fraction(1)
        # eliminate below
