def solve(n):
    """Return the number of prime numbers strictly less than ``n``.
    Handles non‑integer or negative inputs by treating them as 0, returning 0.
    Uses the Sieve of Eratosthenes with a bytearray for efficiency.
    """
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    # Sieve up to n-1
    sieve = bytearray(b'\x01') * n
    sieve[0:2] = b'\x00\x00'
    import math
    limit = int(math.isqrt(n - 1))
    for i in range(2, limit + 1):
        if sieve[i]:
            start = i * i
            step = i
            sieve[start:n:step] = b'\x00' * ((n - 1 - start) // step + 1)
    return sum(sieve)

