def solve(n, b):
    """Convert integer n to its representation in base b (2 <= b <= 36).
    Uses digits 0-9 and lowercase a-z. Negative numbers get a leading '-'.
    """
    if b < 2 or b > 36:
        raise ValueError('Base out of supported range')
    if n == 0:
        return '0'
    sign = '-' if n < 0 else ''
    n = abs(n)
    digits = []
    while n:
        rem = n % b
        if rem < 10:
            digits.append(str(rem))
        else:
            digits.append(chr(ord('a') + rem - 10))
        n //= b
    return sign + ''.join(reversed(digits))

