def solve(s: str) -> bool:
    """Validate an IPv4 address.
    Accepts optional surrounding whitespace.
    Returns True if s consists of four decimal numbers 0-255 with no leading zeros (except '0').
    """
    if not isinstance(s, str):
        return False
    s = s.strip()
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        if not part.isdigit():
            return False
        # Leading zero check
        if len(part) > 1 and part[0] == '0':
            return False
        val = int(part)
        if val < 0 or val > 255:
            return False
    return True
